cd ~/DEV/Flint && python3 -I - <<'EOF'
import csv,re,glob
mv=list(csv.DictReader(open('data/drive_dedupe_2026-10-22/move_log.csv')))
paths={x['move_path'] for x in mv}
tails={x['move_path'].split('/',1)[1] if '/' in x['move_path'] else x['move_path'] for x in mv}
hits=[]
for f in glob.glob('docs/shortlists/*.md')+['docs/QUEUE.md']:
    for p in re.findall(r'`([^`]+\.(?:pdf|pptx?|mp4|wav|mp3|docx|m4a|mov))`',open(f).read()):
        if p in tails or any(p in t for t in tails): hits.append((f.split('/')[-1],p[:90]))
print('Flint queue/shortlist paths that were moved:',len(hits))
for h in hits[:15]: print(' ',h)
import collections
print(collections.Counter('/'.join(x['move_path'].split('/')[:3]) for x in mv if x['move_root']=='04_RESEARCH').most_common(5))
EOF

