input.command:
cd ~/DEV/Flint && python3 -I - <<'EOF'
import json,subprocess
roots=json.load(open('config/roots.json'))['roots']
def get(i):
    r=subprocess.run(['gws','drive','files','get','--params',json.dumps({"fileId":i,"fields":"name,parents,trashed","supportsAllDrives":True})],capture_output=True,text=True)
    o=r.stdout[r.stdout.find('{'):]
    try: return json.loads(o)
    except: return {"err":(r.stdout+r.stderr)[-120:]}
for x in roots:
    d=get(x['id']); chain=[]; p=d.get('parents',[None])[0]
    while p and len(chain)<6:
        q=get(p); 
        if 'name' not in q: break
        chain.append(q['name']); p=q.get('parents',[None])[0]
    print(f"{x['label'][:26]:26} -> {d.get('name',d.get('err'))} | trashed={d.get('trashed')} | in: {'/'.join(reversed(chain))}")
EOF

